q[7] = -2.8973000049591064 + (q[7] * 5.794600009918213);
q[8] = -0.017500000074505806 + (q[8] * 3.7699999809265137);
q[9] = -2.8973000049591064 + (q[9] * 5.794600009918213);
q[10] = -2.8973000049591064 + (q[10] * 5.794600009918213);
q[11] = -1.7627999782562256 + (q[11] * 3.525599956512451);
